/// Priority of a recommendation.
enum RecommendationPriority {
  critical,
  high,
  medium,
  low,
}

/// Recommended action generated by the
/// Property Health Engine.
class Recommendation {
  /// Unique identifier.
  final String id;

  /// Recommendation title.
  final String title;

  /// Explanation.
  final String description;

  /// Estimated PHI improvement.
  final int estimatedPHIGain;

  /// Priority.
  final RecommendationPriority priority;

  /// Suggested evidence/documents.
  final List<String> requiredDocuments;

  const Recommendation({
    required this.id,
    required this.title,
    required this.description,
    required this.estimatedPHIGain,
    required this.priority,
    this.requiredDocuments = const [],
  });

  bool get isCritical =>
      priority == RecommendationPriority.critical;

  @override
  String toString() {
    return 'Recommendation(title: $title, gain: +$estimatedPHIGain)';
  }
}